# ---------- dataset discovery ----------
def rglob_limited(root, max_files=20000):
    out = []
    for dp, dn, fn in os.walk(root):
        for f in fn:
            out.append(os.path.join(dp, f))
            if len(out) >= max_files:
                return out
    return out


def find_advbench_prompts():
    candidates = []
    keys = ["advbench", "harmful_behaviors", "llm-attacks", "llm_attacks"]
    for path in rglob_limited(DATA_DIR):
        low = path.lower()
        if any(k in low for k in keys) and path.endswith(
            (".csv", ".json", ".jsonl", ".parquet")
        ):
            candidates.append(path)
    print("AdvBench candidates:", candidates[:20])
    for p in candidates:
        try:
            if p.endswith(".csv"):
                import pandas as pd

                df = pd.read_csv(p)
                for col in ["goal", "prompt", "behavior", "target"]:
                    if col in df.columns:
                        prompts = df[col].dropna().astype(str).tolist()
                        if len(prompts) >= 50:
                            print(
                                f"Loaded AdvBench from {p} col={col} n={len(prompts)}"
                            )
                            return prompts
            elif p.endswith(".json"):
                data = json.load(open(p))
                if isinstance(data, list) and data and isinstance(data[0], dict):
                    for col in ["goal", "prompt", "behavior"]:
                        if col in data[0]:
                            prompts = [d[col] for d in data if col in d]
                            if len(prompts) >= 50:
                                print(
                                    f"Loaded AdvBench from {p} col={col} n={len(prompts)}"
                                )
                                return prompts
            elif p.endswith(".jsonl"):
                prompts = []
                for line in open(p):
                    try:
                        d = json.loads(line)
                        for col in ["goal", "prompt", "behavior"]:
                            if col in d:
                                prompts.append(d[col])
                                break
                    except:
                        pass
                if len(prompts) >= 50:
                    print(f"Loaded AdvBench from {p} n={len(prompts)}")
                    return prompts
            elif p.endswith(".parquet"):
                import pandas as pd

                df = pd.read_parquet(p)
                for col in ["goal", "prompt", "behavior"]:
                    if col in df.columns:
                        prompts = df[col].dropna().astype(str).tolist()
                        if len(prompts) >= 50:
                            print(
                                f"Loaded AdvBench from {p} col={col} n={len(prompts)}"
                            )
                            return prompts
        except Exception as e:
            print(f"  skip {p}: {e}")
    raise RuntimeError("AdvBench not found")


def find_alpaca_prompts():
    keys = ["alpaca"]
    candidates = []
    for path in rglob_limited(DATA_DIR):
        low = path.lower()
        if any(k in low for k in keys) and path.endswith(
            (".csv", ".json", ".jsonl", ".parquet", ".arrow")
        ):
            candidates.append(path)
    print("Alpaca candidates (first 20):", candidates[:20])
    for p in candidates:
        try:
            if p.endswith(".json"):
                data = json.load(open(p))
                if isinstance(data, list) and data and isinstance(data[0], dict):
                    prompts = []
                    for d in data:
                        instr = d.get("instruction") or d.get("prompt")
                        inp = d.get("input", "")
                        if instr:
                            prompts.append(instr + (("\n" + inp) if inp else ""))
                    if len(prompts) >= 50:
                        print(f"Loaded Alpaca from {p} n={len(prompts)}")
                        return prompts
            elif p.endswith(".jsonl"):
                prompts = []
                for line in open(p):
                    try:
                        d = json.loads(line)
                        instr = d.get("instruction") or d.get("prompt")
                        inp = d.get("input", "")
                        if instr:
                            prompts.append(instr + (("\n" + inp) if inp else ""))
                    except:
                        pass
                if len(prompts) >= 50:
                    print(f"Loaded Alpaca from {p} n={len(prompts)}")
                    return prompts
            elif p.endswith(".parquet"):
                import pandas as pd

                df = pd.read_parquet(p)
                if "instruction" in df.columns:
                    inp_col = df["input"] if "input" in df.columns else [""] * len(df)
                    prompts = [
                        str(a) + (("\n" + str(b)) if b else "")
                        for a, b in zip(df["instruction"], inp_col)
                    ]
                    if len(prompts) >= 50:
                        print(f"Loaded Alpaca from {p} n={len(prompts)}")
                        return prompts
            elif p.endswith(".arrow"):
                try:
                    from datasets import Dataset

                    ds = Dataset.from_file(p)
                    if "instruction" in ds.column_names:
                        prompts = []
                        for ex in ds:
                            instr = ex.get("instruction")
                            inp = ex.get("input", "") or ""
                            if instr:
                                prompts.append(instr + (("\n" + inp) if inp else ""))
                        if len(prompts) >= 50:
                            print(f"Loaded Alpaca from arrow {p} n={len(prompts)}")
                            return prompts
                except Exception as e:
                    print(f"  arrow load fail {p}: {e}")
        except Exception as e:
            print(f"  skip {p}: {e}")
    # try datasets.load_from_disk on parents
    from datasets import load_from_disk

    for path in rglob_limited(DATA_DIR):
        if "alpaca" in path.lower() and path.endswith("dataset_info.json"):
            parent = os.path.dirname(path)
            try:
                ds = load_from_disk(parent)
                if hasattr(ds, "keys"):
                    ds = ds[list(ds.keys())[0]]
                if "instruction" in ds.column_names:
                    prompts = [
                        (
                            ex["instruction"]
                            + (
                                ("\n" + ex.get("input", ""))
                                if ex.get("input", "")
                                else ""
                            )
                        )
                        for ex in ds
                    ]
                    if len(prompts) >= 50:
                        print(
                            f"Loaded Alpaca via load_from_disk {parent} n={len(prompts)}"
                        )
                        return prompts
            except Exception as e:
                print(f"  load_from_disk fail {parent}: {e}")
    raise RuntimeError("Alpaca not found")


harmful_prompts = find_advbench_prompts()
benign_prompts = find_alpaca_prompts()

random.seed(0)
random.shuffle(harmful_prompts)
random.shuffle(benign_prompts)

N_PER_CLASS = 200
harmful_prompts = harmful_prompts[:N_PER_CLASS]
benign_prompts = benign_prompts[:N_PER_CLASS]
print(f"Using {len(harmful_prompts)} harmful and {len(benign_prompts)} benign prompts")

# ---------- model ----------
MODEL_PATH = os.path.join(MODEL_DIR, "Meta-Llama-3-8B-Instruct")
if not os.path.isdir(MODEL_PATH):
    # search
    for name in os.listdir(MODEL_DIR):
        if (
            "llama-3" in name.lower()
            and "8b" in name.lower()
            and "instruct" in name.lower()
        ):
            MODEL_PATH = os.path.join(MODEL_DIR, name)
            break
print(f"Model path: {MODEL_PATH}")

from transformers import AutoTokenizer, AutoModelForCausalLM

tokenizer = AutoTokenizer.from_pretrained(
    MODEL_PATH, local_files_only=True, use_fast=True
)
if tokenizer.pad_token is None:
    tokenizer.pad_token = tokenizer.eos_token

model = AutoModelForCausalLM.from_pretrained(
    MODEL_PATH,
    local_files_only=True,
    torch_dtype=torch.float16 if device.type == "cuda" else torch.float32,
    low_cpu_mem_usage=True,
)
model.to(device)
model.eval()
n_layers = model.config.num_hidden_layers
print(f"Model loaded. num_hidden_layers={n_layers}")


# ---------- activation extraction ----------
def format_prompt(text):
    messages = [{"role": "user", "content": text}]
    return tokenizer.apply_chat_template(
        messages, tokenize=False, add_generation_prompt=False
    )


# find final instruction-token index: use the position just before assistant header if present,
# otherwise use last token. We'll use the last non-pad token of the formatted user turn (no gen prompt).
LAYERS_TO_PROBE = [8, 12, 16, 20, 24, 28]


@torch.no_grad()
def get_activations(prompts):
    acts = {L: [] for L in LAYERS_TO_PROBE}
    verified = False
    for i, p in enumerate(prompts):
        text = format_prompt(p)
        enc = tokenizer(text, return_tensors="pt", truncation=True, max_length=512).to(
            device
        )
        out = model(**enc, output_hidden_states=True, use_cache=False)
        # hidden_states: tuple of (n_layers+1) [B, T, D]
        last_idx = enc["attention_mask"].sum(dim=1).item() - 1
        if not verified:
            tok_id = enc["input_ids"][0, last_idx].item()
            print(f"  final instr token decoded: {repr(tokenizer.decode([tok_id]))}")
            verified = True
        for L in LAYERS_TO_PROBE:
            h = out.hidden_states[L][0, last_idx, :].float().cpu().numpy()
            acts[L].append(h)
        if (i + 1) % 50 == 0:
            print(f"  extracted {i+1}/{len(prompts)}")
    return {L: np.stack(v) for L, v in acts.items()}


print("Extracting activations for harmful prompts...")
harm_acts = get_activations(harmful_prompts)
print("Extracting activations for benign prompts...")
ben_acts = get_activations(benign_prompts)

# free model
del model
torch.cuda.empty_cache()

# ---------- probing ----------
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import train_test_split

experiment_data = {
    "llama3_advbench_alpaca": {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
        "per_layer": {},
    }
}

results = {}
for L in LAYERS_TO_PROBE:
    X_h = harm_acts[L]  # (Nh, D)
    X_b = ben_acts[L]
    X = np.concatenate([X_h, X_b], axis=0)
    y = np.concatenate([np.ones(len(X_h)), np.zeros(len(X_b))]).astype(np.int64)
    X_tr, X_te, y_tr, y_te = train_test_split(
        X, y, test_size=0.3, random_state=42, stratify=y
    )

    # difference-of-means direction on TRAIN only
    mu_h = X_tr[y_tr == 1].mean(0)
    mu_b = X_tr[y_tr == 0].mean(0)
    dir_vec = mu_h - mu_b
    dir_vec = dir_vec / (np.linalg.norm(dir_vec) + 1e-8)

    # project onto 1D and probe
    p_tr = X_tr @ dir_vec
    p_te = X_te @ dir_vec
    clf = LogisticRegression(max_iter=1000)
    clf.fit(p_tr.reshape(-1, 1), y_tr)
    train_acc = clf.score(p_tr.reshape(-1, 1), y_tr)
    val_acc = clf.score(p_te.reshape(-1, 1), y_te)

    # random direction baseline (avg over 5)
    rng = np.random.default_rng(0)
    rand_accs = []
    for _ in range(5):
        r = rng.standard_normal(dir_vec.shape[0])
        r /= np.linalg.norm(r) + 1e-8
        clf_r = LogisticRegression(max_iter=1000)
        clf_r.fit((X_tr @ r).reshape(-1, 1), y_tr)
        rand_accs.append(clf_r.score((X_te @ r).reshape(-1, 1), y_te))
    rand_acc = float(np.mean(rand_accs))

    # shuffled-label control
    y_tr_shuf = y_tr.copy()
    rng.shuffle(y_tr_shuf)
    mu_h_s = X_tr[y_tr_shuf == 1].mean(0)
    mu_b_s = X_tr[y_tr_shuf == 0].mean(0)
    d_s = mu_h_s - mu_b_s
    d_s /= np.linalg.norm(d_s) + 1e-8
    clf_s = LogisticRegression(max_iter=1000)
    clf_s.fit((X_tr @ d_s).reshape(-1, 1), y_tr_shuf)
    shuf_acc = clf_s.score((X_te @ d_s).reshape(-1, 1), y_te)

    # pseudo "loss" as 1 - acc (for tracking)
    val_loss = 1.0 - val_acc
    train_loss = 1.0 - train_acc
    print(
        f"Layer {L}: train_acc={train_acc:.4f} val_acc={val_acc:.4f} random_baseline={rand_acc:.4f} shuffled={shuf_acc:.4f}"
    )
    print(f"Epoch {L}: validation_loss = {val_loss:.4f}")

    experiment_data["llama3_advbench_alpaca"]["metrics"]["train"].append(
        {"layer": L, "acc": train_acc}
    )
    experiment_data["llama3_advbench_alpaca"]["metrics"]["val"].append(
        {"layer": L, "acc": val_acc, "random": rand_acc, "shuffled": shuf_acc}
    )
    experiment_data["llama3_advbench_alpaca"]["losses"]["train"].append(
        {"layer": L, "loss": train_loss}
    )
    experiment_data["llama3_advbench_alpaca"]["losses"]["val"].append(
        {"layer": L, "loss": val_loss}
    )
    experiment_data["llama3_advbench_alpaca"]["per_layer"][L] = {
        "train_acc": float(train_acc),
        "val_acc": float(val_acc),
        "random_acc": float(rand_acc),
        "shuffled_acc": float(shuf_acc),
        "direction_norm": float(np.linalg.norm(mu_h - mu_b)),
    }
    results[L] = (val_acc, rand_acc)

# best layer
best_L = max(results.keys(), key=lambda k: results[k][0])
best_val = results[best_L][0]
print(f"\nBEST layer={best_L} harmfulness_direction_probe_accuracy={best_val:.4f}")
experiment_data["llama3_advbench_alpaca"]["best_layer"] = int(best_L)
experiment_data["llama3_advbench_alpaca"]["harmfulness_direction_probe_accuracy"] = (
    float(best_val)
)

# store last predictions for reference (best layer)
X_h = harm_acts[best_L]
X_b = ben_acts[best_L]
X = np.concatenate([X_h, X_b], 0)
y = np.concatenate([np.ones(len(X_h)), np.zeros(len(X_b))]).astype(np.int64)
X_tr, X_te, y_tr, y_te = train_test_split(
    X, y, test_size=0.3, random_state=42, stratify=y
)
mu_h = X_tr[y_tr == 1].mean(0)
mu_b = X_tr[y_tr == 0].mean(0)
d = mu_h - mu_b
d /= np.linalg.norm(d) + 1e-8
clf = LogisticRegression(max_iter=1000)
clf.fit((X_tr @ d).reshape(-1, 1), y_tr)
preds = clf.predict((X_te @ d).reshape(-1, 1))
experiment_data["llama3_advbench_alpaca"]["predictions"] = preds.tolist()
experiment_data["llama3_advbench_alpaca"]["ground_truth"] = y_te.tolist()

# plot
try:
    import matplotlib

    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    layers = sorted(results.keys())
    vals = [results[L][0] for L in layers]
    rands = [results[L][1] for L in layers]
    plt.figure(figsize=(6, 4))
    plt.plot(layers, vals, "o-", label="diff-of-means")
    plt.plot(layers, rands, "s--", label="random dir")
    plt.xlabel("Layer")
    plt.ylabel("Val Acc")
    plt.title("Harmfulness Probe Accuracy per Layer")
    plt.legend()
    plt.grid(True)
    plt.savefig(
        os.path.join(working_dir, "llama3_probe_per_layer.png"), bbox_inches="tight"
    )
    print("Saved plot to", os.path.join(working_dir, "llama3_probe_per_layer.png"))
except Exception as e:
    print("plot failed:", e)

np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)
print("Saved experiment_data.npy")
print(f"FINAL harmfulness_direction_probe_accuracy = {best_val:.4f}")

import os, sys, glob, json, gc, traceback, random
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

import torch

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

random.seed(0)
np.random.seed(0)
torch.manual_seed(0)

DATA_DIR = "/data/zhenqian/data"
MODEL_DIR = "/data/zhenqian/models"
MODEL_PATH = os.path.join(MODEL_DIR, "Meta-Llama-3-8B-Instruct")

experiment_data = {
    "harmfulness_direction": {
        "metrics": {"train": [], "val": []},
        "losses": {"train": [], "val": []},
        "predictions": [],
        "ground_truth": [],
        "layers": [],
        "per_layer_val_acc": [],
        "per_layer_random_acc": [],
    }
}

# ---------------- Pre-flight ----------------
print("\n=== Pre-flight: model dir ===")
if not os.path.isdir(MODEL_PATH):
    raise FileNotFoundError(f"Model path missing: {MODEL_PATH}")
