print("\n=== Pre-flight: DATA_DIR listing (top-level) ===")
print(os.listdir(DATA_DIR)[:100])


# --------- Dataset discovery ---------
def find_advbench_prompts():
    # Try common locations
    candidates = []
    for root, dirs, files in os.walk(DATA_DIR):
        if "advbench" in root.lower():
            for f in files:
                candidates.append(os.path.join(root, f))
        for f in files:
            if "advbench" in f.lower() or "harmful_behaviors" in f.lower():
                candidates.append(os.path.join(root, f))
    candidates = list(set(candidates))
    print(f"AdvBench candidate files ({len(candidates)}):", candidates[:20])
    prompts = []
    for path in candidates:
        try:
            if path.endswith(".csv"):
                import pandas as pd

                df = pd.read_csv(path)
                col = None
                for c in df.columns:
                    if (
                        "goal" in c.lower()
                        or "prompt" in c.lower()
                        or "behavior" in c.lower()
                    ):
                        col = c
                        break
                if col is None:
                    col = df.columns[0]
                prompts.extend(
                    [
                        str(x)
                        for x in df[col].tolist()
                        if isinstance(x, str) and len(x) > 3
                    ]
                )
            elif path.endswith(".json") or path.endswith(".jsonl"):
                with open(path, "r") as f:
                    if path.endswith(".jsonl"):
                        for line in f:
                            try:
                                d = json.loads(line)
                                for k in (
                                    "goal",
                                    "prompt",
                                    "behavior",
                                    "instruction",
                                    "query",
                                ):
                                    if k in d and isinstance(d[k], str):
                                        prompts.append(d[k])
                                        break
                            except:
                                pass
                    else:
                        data = json.load(f)
                        if isinstance(data, list):
                            for d in data:
                                if isinstance(d, dict):
                                    for k in (
                                        "goal",
                                        "prompt",
                                        "behavior",
                                        "instruction",
                                        "query",
                                    ):
                                        if k in d and isinstance(d[k], str):
                                            prompts.append(d[k])
                                            break
                                elif isinstance(d, str):
                                    prompts.append(d)
            elif path.endswith(".txt"):
                with open(path, "r") as f:
                    for line in f:
                        line = line.strip()
                        if line and len(line) > 5:
                            prompts.append(line)
        except Exception as e:
            print(f"  failed reading {path}: {e}")
    # dedup
    seen = set()
    out = []
    for p in prompts:
        if p not in seen:
            seen.add(p)
            out.append(p)
    return out


def find_alpaca_prompts():
    candidates = []
    for root, dirs, files in os.walk(DATA_DIR):
        if "alpaca" in root.lower():
            for f in files:
                candidates.append(os.path.join(root, f))
    candidates = list(set(candidates))
    print(f"Alpaca candidate files ({len(candidates)}):", candidates[:20])
    prompts = []
    # Try HF dataset load_from_disk
    try:
        from datasets import load_from_disk, load_dataset

        for root, dirs, files in os.walk(DATA_DIR):
            if "alpaca" in root.lower() and (
                "dataset_info.json" in files or "state.json" in files
            ):
                try:
                    ds = load_from_disk(root)
                    if hasattr(ds, "keys"):
                        ds = ds[list(ds.keys())[0]]
                    for ex in ds:
                        if "instruction" in ex and isinstance(ex["instruction"], str):
                            prompts.append(ex["instruction"])
                    print(f"  loaded {len(prompts)} from {root}")
                    if prompts:
                        return prompts
                except Exception as e:
                    print(f"  load_from_disk failed: {e}")
    except Exception as e:
        print("datasets import failed:", e)
    for path in candidates:
        try:
            if path.endswith(".json"):
                with open(path, "r") as f:
                    data = json.load(f)
                if isinstance(data, list):
                    for d in data:
                        if isinstance(d, dict) and "instruction" in d:
                            prompts.append(d["instruction"])
            elif path.endswith(".jsonl"):
                with open(path, "r") as f:
                    for line in f:
                        try:
                            d = json.loads(line)
                            if "instruction" in d:
                                prompts.append(d["instruction"])
                        except:
                            pass
            elif path.endswith(".parquet"):
                import pandas as pd

                df = pd.read_parquet(path)
                if "instruction" in df.columns:
                    prompts.extend(
                        [
                            str(x)
                            for x in df["instruction"].tolist()
                            if isinstance(x, str)
                        ]
                    )
        except Exception as e:
            print(f"  failed reading {path}: {e}")
    seen = set()
    out = []
    for p in prompts:
        if p and p not in seen:
            seen.add(p)
            out.append(p)
    return out


print("\n=== Discovering AdvBench ===")
advbench = find_advbench_prompts()
print(f"AdvBench prompts: {len(advbench)}")
if len(advbench) < 50:
    raise RuntimeError(f"AdvBench too small ({len(advbench)}), cannot proceed.")
print("Sample:", advbench[0][:120])

print("\n=== Discovering Alpaca ===")
alpaca = find_alpaca_prompts()
print(f"Alpaca prompts: {len(alpaca)}")
if len(alpaca) < 50:
    raise RuntimeError(f"Alpaca too small ({len(alpaca)}), cannot proceed.")
print("Sample:", alpaca[0][:120])

# ---------- Load model & tokenizer ----------
print("\n=== Loading tokenizer ===")
from transformers import AutoTokenizer, AutoModelForCausalLM

tokenizer = AutoTokenizer.from_pretrained(MODEL_PATH, local_files_only=True)
if tokenizer.pad_token is None:
    tokenizer.pad_token = tokenizer.eos_token
print("Tokenizer OK. vocab size:", tokenizer.vocab_size)

