def format_prompt(instr):
    # Use chat template; do NOT add generation prompt so that the LAST token
    # is the final instruction/eot token (end of user message).
    msgs = [{"role": "user", "content": instr}]
    text = tokenizer.apply_chat_template(
        msgs, tokenize=False, add_generation_prompt=False
    )
    return text


