def load_tokenizer(path):
    # Try multiple strategies
    errors = []
    for attempt in ["fast", "slow", "install_tiktoken", "install_sentencepiece"]:
        try:
            if attempt == "fast":
                tok = AutoTokenizer.from_pretrained(
                    path, local_files_only=True, use_fast=True
                )
                print("Loaded fast tokenizer")
                return tok
            elif attempt == "slow":
                tok = AutoTokenizer.from_pretrained(
                    path, local_files_only=True, use_fast=False
                )
                print("Loaded slow tokenizer")
                return tok
            elif attempt == "install_tiktoken":
                print("Attempting to install tiktoken...")
                subprocess.check_call(
                    [
                        sys.executable,
                        "-m",
                        "pip",
                        "install",
                        "tiktoken",
                        "blobfile",
                        "--quiet",
                    ]
                )
                import importlib as _il
                import tiktoken  # noqa

                tok = AutoTokenizer.from_pretrained(
                    path, local_files_only=True, use_fast=True
                )
                print("Loaded tokenizer after installing tiktoken")
                return tok
            elif attempt == "install_sentencepiece":
                print("Attempting to install sentencepiece...")
                subprocess.check_call(
                    [sys.executable, "-m", "pip", "install", "sentencepiece", "--quiet"]
                )
                tok = AutoTokenizer.from_pretrained(
                    path, local_files_only=True, use_fast=False
                )
                print("Loaded tokenizer after installing sentencepiece")
                return tok
        except Exception as e:
            errors.append(f"{attempt}: {e}")
            print(f"  tokenizer attempt {attempt} failed: {e}")
    raise RuntimeError("All tokenizer loading strategies failed:\n" + "\n".join(errors))


